    const matchesGrade = gradeFilter === 'All' || s.grade === gradeFilter;
    const matchesAttendance = attendanceFilter === 'All' || s.attendanceStatus === attendanceFilter;
    return matchesSearch && matchesGrade && matchesAttendance;
