                              <View style={{ flex: 1 }}>
                                <Text style={styles.leaveApplicantName}>{leave.applicantName}</Text>
                                <Text style={styles.leaveSubmittedDate}>Submitted: {leave.submittedAt}</Text>
                              </View>
